Translate("ptBR", "aetheen-of-the-gales", {
	title = "Aetheen of the Gales",
	subtitle = "Anciã de Zephras Isle",
	found = "Thendal Village",
	hint = [=[Procure a anciã do conselho que observa os jovens em Thendal Village.]=],
	allegiance = "Conselho dos Anciões · Zephras Isle",
	aliases = { "Aetheen" },
	sections = {
		{
			title = "Resumo",
			text = [=[Aetheen of the Gales é membro do Conselho dos Anciões de {link:zephras-isle}Zephras Isle{/link}. Ela veio a {link:thendal-village}Thendal Village{/link} para ler o fluxo dos ventos no bosque e para julgar os jovens {link:skyborne}shen'dorei{/link} que ali atingem a maioridade. Ela observa antes de falar. Quando um jovem a encontra, ela já sabe muito sobre ele.]=],
		},
		{
			title = "Importância",
			text = [=[Aetheen é o olho do conselho sobre a próxima geração. Num tempo em que a ilha precisa de cada mão capaz, ela decide quais jovens estão prontos para deixar o abrigo do bosque. Está também entre os primeiros a nomear claramente o perigo para eles: os {link:al-aketh}Al'Aketh{/link}, fanáticos de um "suposto" soberano de {link:skywall}Skywall{/link}, cujo poder e ambições crescem a cada dia.]=],
		},
		{
			title = "Feitos",
			text = [=[• Lê os ventos do {link:thendal-village}Thendal Grove{/link} para o conselho.
• Testa os jovens enviando-os contra os ursera e sua mãe da toca.
• Envia-os ao sul, à {link:constable-aonda}Condestável Aonda{/link} em {link:shen-dar-village}Shen'dar Village{/link}, que o culto ameaça.
• Envia outros para aprender os caminhos da natureza com um andarilho perto de Shen'dar.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Pouco se escreveu sobre a vida de Aetheen antes destes dias. Não está registrado se ela pertence a alguma das ordens, nem há quanto tempo tem assento no conselho.]=],
		},
	},
	chapters = {
		{
			title = "O Próximo Passo",
			hint = "Passe na prova da anciã e vá aonde ela o enviar.",
			text = [=[Nas cavernas ao sul do bosque, os ursera haviam ficado famintos e desesperados, liderados por uma mãe da toca que os patrulheiros chamavam de Urs'anah. Aetheen enviou o jovem até lá como prova de determinação. Quando a prova foi vencida, ela não o elogiou por muito tempo. Mandou-o para o sul, onde o culto pressionava {link:shen-dar-village}Shen'dar Village{/link}, e disse-lhe que contasse que ela o enviara.]=],
		},
	},
	mentions = {
		{ text = "Aetheen of the Gales" },
		{ text = "Matriarca Imunda" },
		{ text = "O Aventureiro" },
	},
	bonds = {
		{ id = "rorian-the-dayseeker", name = "Rorian the Dayseeker", note = "envia os jovens a ela" },
		{ id = "constable-aonda", name = "Condestável Aonda", note = "uma boa mulher, nas palavras dela" },
		{ id = "talaanis-shadowsong", name = "Talaanis Shadowsong", note = "Ancião Supremo de seu conselho" },
	},
})

Translate("ptBR", "high-priestess-lorthuna", {
	title = "Suma Sacerdotisa Lorthuna",
	subtitle = "Suma Sacerdotisa dos Al'Aketh",
	found = "O Shrine of Akir e os pináculos acima dele",
	hint = "Enfrente a suma sacerdotisa do culto do Senhor dos Ventos.",
	allegiance = "Al'Aketh",
	aliases = { "Lorthuna" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Suma Sacerdotisa Lorthuna lidera os {link:al-aketh}Al'Aketh{/link}, o culto de {link:al-akir}Al'Akir{/link} em {link:zephras-isle}Zephras Isle{/link}. Ela foi outrora uma {link:windshapers}Windshaper{/link} e irmã da ordem de {link:ayessa-dawnsinger}Ayessa Dawnsinger{/link}. Agora governa o {link:shrine-of-akir}Shrine of Akir{/link} e fala de uma grande obra que trará o Senhor dos Ventos ao seu povo. É fria, astuta e cruel, e seus seguidores se chamam instrumentos de sua vontade.]=],
		},
		{
			title = "Importância",
			text = [=[Lorthuna viu o que o resto de seu povo não via: que os pilares de {link:zephras-isle}Zephras{/link} eram proteções além de âncoras. Ela transformou esse segredo numa arma. Seu culto tomou {link:falaath-village}Falaath Village{/link}, atacou as torres de vigia dos pilares e derrubou as proteções. O que quer que tenha sido feito dela, sua obra não pode ser desfeita. Zephras agora jaz exposta diante de seu {link:al-akir}Senhor dos Ventos{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Enviou saqueadores e pregadores por toda a ilha a partir do {link:shrine-of-akir}Shrine of Akir{/link}.
• Encontrou o {link:skypriest-aanders}Sacerdote Celeste Aanders{/link} em Falaath e pôs em marcha seus ataques contra Shen'dar e a {link:west-pylon-watchtower}torre de vigia do oeste{/link}.
• Mandou matar o enviado da {link:high-order}High Order{/link} {link:belathaan-brightwish}Belathaan Brightwish{/link} e devolveu a língua dele a {link:valanaar}Valanaar{/link}.
• Acendeu um farol nos {link:rohashi-spires}Rohashi Spires{/link} para os servos do {link:al-akir}Senhor dos Ventos{/link}.]=],
		},
	},
	chapters = {
		{
			title = "A Hóspede de Falaath",
			hint = "Descubra o que o culto planeja para as Shen'dar Highlands.",
			text = [=[Um recruta que se misturou aos fiéis de Falaath foi mandado ficar longe da estalagem, onde o sacerdote celeste recebia uma visita. A visita era Lorthuna. Suas ordens foram breves. Ela tinha outros assuntos, e aquilo era apenas uma peça de seu jogo. {link:skypriest-aanders}Aanders{/link} tomaria a {link:west-pylon-watchtower}torre de vigia do oeste{/link}, e Cyclas tomaria {link:shen-dar-village}Shen'dar Village{/link}.]=],
		},
		{
			title = "O Farol",
			hint = [=[Siga a suma sacerdotisa até os pináculos acima de seu santuário.]=],
			text = [=[Nos pináculos, Lorthuna disse a seus inimigos que haviam chegado tarde demais. As proteções estavam caídas havia dias. Ela estava acendendo um farol. Quando o Senhor do Vento Leste chegou, ela o saudou e pediu para ser levada diante do {link:al-akir}Senhor dos Ventos{/link} como arauto de sua glória. {link:rohash}Rohash{/link} a golpeou para o lado e a lançou voando no céu sem fim.]=],
		},
	},
	mentions = {
		{ text = "Brutamontes {link:al-aketh}Al'Aketh{/link}" },
		{ text = "Vingado Dez Vezes" },
		{ text = "Os Verdadeiros Planos do Culto" },
	},
	bonds = {
		{ id = "ayessa-dawnsinger", name = "Ayessa Dawnsinger", note = "sua antiga irmã" },
		{ id = "skypriest-aanders", name = "Sacerdote Celeste Aanders", note = "seu servo em Falaath" },
		{ id = "belathaan-brightwish", name = "Belathaan Brightwish", note = "o enviado que ela matou" },
		{ id = "rohash", name = "Rohash", note = "respondeu a seu farol" },
		{ id = "al-akir", name = "Al'Akir", note = "o senhor a quem ela servia" },
	},
})

Translate("ptBR", "rohash", {
	title = "Rohash",
	subtitle = "Senhor do Vento Leste",
	found = "Os Rohashi Spires, acima do Shrine of Akir",
	hint = "Enfrente o senhor do vento que respondeu ao farol do culto.",
	allegiance = "Al'Akir · Skywall",
	sections = {
		{
			title = "Resumo",
			text = [=[Rohash é o Senhor do Vento Leste, um dos grandes senhores do ar que servem a {link:al-akir}Al'Akir{/link} em {link:skywall}Skywall{/link}. É poderoso, zombeteiro e se deleita com o sofrimento de seres menores. Veio a {link:zephras-isle}Zephras Isle{/link} quando o farol de {link:high-priestess-lorthuna}Lorthuna{/link} o chamou.]=],
		},
		{
			title = "Importância",
			text = [=[Rohash é o primeiro servo do {link:al-akir}Senhor dos Ventos{/link} de que se sabe ter visto {link:zephras-isle}Zephras Isle{/link}. Nunca ouvira falar da ilha nem de seu povo. A descoberta o assombrou, e ele entendeu na hora o que significava. Os espíritos que haviam abrigado os elfos eram seus próprios "irmãos rebeldes", e tinham escondido bem a ilha. Com as proteções caídas, ele podia levar o segredo a seu senhor.]=],
		},
		{
			title = "Feitos",
			text = [=[• Respondeu ao farol de {link:high-priestess-lorthuna}Lorthuna{/link} nos {link:rohashi-spires}Rohashi Spires{/link}.
• Lançou para longe a suma sacerdotisa quando ela ousou lhe dar ordens.
• Convocou os exércitos do {link:al-akir}Senhor dos Ventos{/link} contra os elfos.
• Retirou-se quando a {link:earthen-ring}Harmonia Telúrica{/link} e o {link:kirin-tor}Kirin Tor{/link} ficaram ao lado dos {link:skyborne}shen'dorei{/link}.
• Zombou da esperança dos elfos de resistir, dizendo que os exércitos de seu senhor eram infinitos naquele reino.]=],
		},
	},
	chapters = {
		{
			title = "O Senhor do Vento Leste",
			hint = "Esteja nos pináculos quando o farol for respondido.",
			text = [=[Rohash riu dos elfos e dos amigos que haviam encontrado em lugares baixos. Perguntou-se em voz alta se seu senhor os escravizaria ou simplesmente os devoraria. Quando {link:muln-earthfury}Muln Earthfury{/link} lhe disse que a Ring não tinha briga com ele, Rohash escolheu partir. Antes de ir, deu aos elfos sua promessa. Eram hóspedes no reino de seu senhor apenas até que viesse o julgamento do {link:al-akir}Senhor dos Ventos{/link}. Não saberiam quando viria, mas viria.]=],
		},
	},
	mentions = {
		{ text = "Confrontar {link:high-priestess-lorthuna}Lorthuna{/link}" },
	},
	bonds = {
		{ id = "al-akir", name = "Al'Akir", note = "seu senhor" },
		{ id = "high-priestess-lorthuna", name = "Suma Sacerdotisa Lorthuna", note = "acendeu o farol a que ele respondeu" },
		{ id = "muln-earthfury", name = "Muln Earthfury", note = "falou pela Harmonia Telúrica diante dele" },
	},
})

