Translate("ptBR", "windshapers", {
	title = "Windshapers",
	aliases = { "Windshaper" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Windshapers são os xamãs e videntes dos {link:skyborne}Skyborne{/link}. Descendem dos primeiros shen'dorei que receberam dos {link:vanishing-of-the-wind-spirits}espíritos do vento{/link} o dom da visão celeste, o poder de ver através do plano elemental. Por eras foram os guias espirituais de {link:zephras-isle}Zephras Isle{/link}. Guardam suas pedras eretas sagradas e cuidam dos construtos e instrumentos que os espíritos deixaram para trás.]=],
		},
		{
			title = "Seu Credo",
			text = [=[Os Windshapers sustentam que seu povo tem com os {link:vanishing-of-the-wind-spirits}espíritos do vento{/link} uma dívida que jamais poderá ser paga por inteiro. Juraram encontrar os espíritos e restaurar os antigos costumes. Sem os espíritos, dizem, ficam quase cegos ao que acontece em {link:skywall}Skywall{/link}. Alguns deles temem que a culpa pela partida dos espíritos seja deles mesmos. Desconfiam da {link:high-order}High Order{/link}, a quem chamam de herdeiros arrogantes dos Bem-nascidos que buscam dominar o que deveriam honrar. Onde a High Order vê nas linhas de energia recém-surgidas um presente, os Windshapers veem feridas na terra.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Sua magia se apagou desde que os espíritos partiram, e há sangue entre eles e a {link:high-order}High Order{/link}. Sua líder, a {link:ayessa-dawnsinger}Grã-Vidente Celeste{/link} Ayessa Dawnsinger, buscou através dos planos com sua visão celeste e encontrou a {link:earthen-ring}Harmonia Telúrica{/link} de {link:azeroth}Azeroth{/link}. Por meio da Ring, os Windshapers se uniram à {link:horde}Horda{/link}. Sua vanguarda agora parte de {link:valanaar}Valanaar{/link} rumo a {link:mulgore}Mulgore{/link}.]=],
		},
	},
})

Translate("ptBR", "high-order", {
	title = "High Order",
	sections = {
		{
			title = "Resumo",
			text = [=[A High Order reúne os magísteres dos {link:skyborne}Skyborne{/link}, os descendentes dos estudiosos Bem-nascidos de Eldre'Thalas. Eles se chamam guardiões dos costumes dos Bem-nascidos. Em dez mil anos em {link:skywall}Skywall{/link}, grande parte de seu saber arcano foi esquecida, e seu poder minguou. Eles pretendem recuperá-lo.]=],
		},
		{
			title = "Seu Credo",
			text = [=[A High Order sustenta que os {link:skyborne}shen'dorei{/link} cometeram um erro grave ao pôr seu destino nas mãos de espíritos volúveis. O desaparecimento dos espíritos o provou. O que os espíritos faziam, crê a ordem, pode ser feito com a magia dos {red:highborne}Bem-nascidos{/red}, e a ilha pode se sustentar sozinha. Eles estudam as linhas de energia recém-surgidas de {link:zephras-isle}Zephras{/link} e a magia elemental das pedras eretas, digam o que disserem os {link:windshapers}Windshapers{/link}. Para os Windshapers, são intrometidos. Para si mesmos, são os únicos dispostos a agir.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[O Magíster Supremo {link:elaadrin-evengale}Elaadrin Evengale{/link} encontrou um jeito de espiar através dos planos, e encontrou o {link:kirin-tor}Kirin Tor{/link} de {link:dalaran}Dalaran{/link} olhando de volta. Por meio do Kirin Tor, a High Order se uniu à {link:alliance}Aliança{/link}. Seus jovens magísteres agora partem de {link:valanaar}Valanaar{/link} rumo a Dalaran para reaver o conhecimento que seus ancestrais perderam.]=],
		},
	},
})

Translate("ptBR", "al-aketh", {
	title = "Al'Aketh",
	aliases = { "Culto Al'Aketh", "culto de Al'Akir" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Al'Aketh são um culto de {link:skyborne}shen'dorei{/link} que adoram {link:al-akir}Al'Akir{/link}, o Senhor dos Ventos. Alguns de seus fundadores usaram a visão celeste para olhar através de {link:skywall}Skywall{/link} e vislumbraram o terrível poder de seu senhor. Tentados por esse poder, romperam com seu povo e se entregaram ao seu serviço. Quando os {link:vanishing-of-the-wind-spirits}espíritos do vento{/link} desapareceram, o culto se ergueu no medo que se seguiu.]=],
		},
		{
			title = "Seu Credo",
			text = [=[O culto prega que os {link:skyborne}shen'dorei{/link} ficaram orgulhosos e ociosos, tomando os dons dos ventos como garantidos, e que os espíritos os deixaram por isso. Só a penitência e o serviço ao {link:al-akir}Senhor dos Ventos{/link} trarão o vento de volta. Seus missionários fingem ser uma fé gentil. Seus brutamontes, chamadores de tempestade e assassinos fazem o resto. Muitos de seus membros foram outrora {link:windshapers}Windshapers{/link}, {link:peacekeepers}Peacekeepers{/link} ou druidas, e {link:ayessa-dawnsinger}Ayessa Dawnsinger{/link} chama o culto de espelho sombrio de sua própria ordem.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Sob a {link:high-priestess-lorthuna}Suma Sacerdotisa Lorthuna{/link}, o culto dominou {link:falaath-village}Falaath Village{/link} e o {link:shrine-of-akir}Shrine of Akir{/link}, saqueou as caravanas da ilha e atacou as torres de vigia dos pilares para derrubar as proteções que escondiam {link:zephras-isle}Zephras{/link}. Sua suma sacerdotisa se foi e seu santuário foi tomado de assalto, mas seu propósito foi cumprido. Os servos do {link:al-akir}Senhor dos Ventos{/link} agora sabem onde fica Zephras.]=],
		},
	},
})

Translate("ptBR", "peacekeepers", {
	title = "Peacekeepers",
	aliases = { "Peacekeeper" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Peacekeepers são a milícia de {link:zephras-isle}Zephras Isle{/link} e o que os {link:skyborne}Skyborne{/link} têm de mais próximo de um exército. Respondem à Capitã {link:valennia-stormfist}Valennia Stormfist{/link} em {link:valanaar}Valanaar{/link} e ao Conselho dos Anciões. Seus condestáveis mantêm a ordem nos vilarejos, e seus soldados guarnecem as torres de vigia que guardam os {link:anchor-pylons}pilares-âncora{/link}.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Por muito tempo os Peacekeepers evitaram a guerra aberta com os {link:al-aketh}Al'Aketh{/link}, esperando que o culto continuasse sendo um incômodo. Essa esperança acabou em {link:shen-dar-village}Shen'dar Village{/link} e nas torres de vigia dos pilares. Em pequeno número, combateram o culto por toda a ilha e lideraram o assalto ao {link:shrine-of-akir}Shrine of Akir{/link}. Também se põem entre os {link:windshapers}Windshapers{/link} e a {link:high-order}High Order{/link}, e sua capitã não tolera que as duas ordens lutem em {link:valanaar}Valanaar{/link}. Nem todos permaneceram leais. {link:commander-belguilos}Belguilos{/link}, a quem o culto agora chama de a Quebradora, outrora vestiu suas cores. Entre os que resistiram estavam a {link:constable-aonda}Condestável Aonda{/link} de Shen'dar, a tenente {link:yorana-windyreed}Yorana Windyreed{/link} na torre do leste e {link:hyusaa-quickbreeze}Hyusaa Quickbreeze{/link}, a imediata da capitã.]=],
		},
	},
})

Translate("ptBR", "anchor-pylons", {
	title = "Pilares-âncora",
	aliases = { "pilar-âncora", "pilares-âncora", "pilares do vento" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os pilares-âncora são antigas torres de magia elemental, presentes dos {link:vanishing-of-the-wind-spirits}espíritos do vento{/link} aos {link:skyborne}shen'dorei{/link}. Eles mantêm {link:zephras-isle}Zephras Isle{/link} unida e a seguram em seu lugar em {link:skywall}Skywall{/link}. Torres de vigia dos {link:peacekeepers}Peacekeepers{/link} ficam ao lado deles, uma no planalto do oeste e outra fora de {link:valanaar}Valanaar{/link}.]=],
		},
		{
			title = "Seu Declínio",
			text = [=[Desde que os espíritos desapareceram, os pilares ficaram instáveis. Seu esplendor não mudou, e nenhum dano se vê, mas sua magia vacila. À medida que ela enfraquece, partes da ilha desmoronam e caem para o céu. Os {link:skyborne}shen'dorei{/link} agora recorrem às pedras do vento para suas necessidades diárias, e a {link:high-order}High Order{/link} espera dominar a magia dos pilares antes que ela falhe de vez.]=],
		},
		{
			title = "As Proteções",
			text = [=[Os {link:skyborne}shen'dorei{/link} haviam meio esquecido um segundo propósito. Os pilares são também proteções. Eles escondiam a ilha do olhar do que mais habita {link:skywall}Skywall{/link}. O {link:flight-from-eldre-thalas}Shal'nan{/link} falou disso certa vez, e os {link:al-aketh}Al'Aketh{/link} o descobriram. Atacaram os pilares para derrubar as proteções, e conseguiram. {link:zephras-isle}Zephras{/link} ainda flutua, mas já não está escondida.]=],
		},
	},
})

Translate("ptBR", "vanishing-of-the-wind-spirits", {
	title = "O Desaparecimento dos Espíritos do Vento",
	aliases = { "espíritos do vento" },
	sections = {
		{
			title = "Resumo",
			text = [=[Por milhares de anos, espíritos do vento viveram em {link:zephras-isle}Zephras Isle{/link} ao lado dos {link:skyborne}shen'dorei{/link}, como patronos, mestres e amigos. Ergueram a ilha, cuidaram de sua magia e deram a seus videntes a visão celeste. Então, há vários séculos, desapareceram. Não deram aviso, e ninguém em Zephras sabe por que partiram nem para onde.]=],
		},
		{
			title = "O Que Se Seguiu",
			text = [=[A magia da ilha começou a se apagar. Os {link:anchor-pylons}pilares-âncora{/link} vacilaram. A maioria dos construtos dos espíritos parou de funcionar. Estranhos espíritos pálidos chamados hollows surgiram na {link:shadowgale-forest}Shadowgale Forest{/link}. As feras ficaram selvagens, e os duendes menores do vento se tornaram violentos quando perturbados. O contato com as outras ilhas se perdeu, e vilarejos inteiros caíram para o céu. Cada facção leu a perda à sua maneira. Os {link:windshapers}Windshapers{/link} desejam encontrar os espíritos e chamá-los de volta. A {link:high-order}High Order{/link} diz que os elfos nunca mais devem depender deles. Os {link:al-aketh}Al'Aketh{/link} pregam que os espíritos abandonaram um povo orgulhoso, e que só resta {link:al-akir}o Senhor dos Ventos{/link}.]=],
		},
	},
})

Translate("ptBR", "flight-from-eldre-thalas", {
	title = "A Fuga de Eldre'Thalas",
	aliases = { "Rebelião em Eldre'Thalas", "Shal'nan" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os {link:skyborne}Skyborne{/link} começaram como rebeldes. Depois da {link:war-of-the-ancients}Guerra dos Antigos{/link}, os {red:highborne}Bem-nascidos{/red} de Eldre'Thalas, a cidade em {link:feralas}Feralas{/link} hoje chamada {red:dire-maul}Gládio Cruel{/red}, ficaram sem o Poço que alimentara sua magia. O Príncipe {red:tortheldrin}Tortheldrin{/red} buscou sustentá-los com poderes cada vez mais sombrios. Parte de seu povo tinha visto aonde tal fome levava, e não deixaria que os erros de {link:azshara}Azshara{/link} se repetissem.]=],
		},
		{
			title = "O Velado",
			text = [=[Os rebeldes eram liderados por uma figura conhecida apenas como o Shal'nan, o Velado, que escondia o rosto atrás de uma máscara de ouro sem feições. Seu nome virou grito de guerra. Com sabotagem e coisa pior, seus seguidores atrapalharam a rede de focos de cristal do príncipe e o envergonharam repetidas vezes. Naqueles dias, o druidismo dos {link:night-elves}elfos noturnos{/link} do norte também se espalhou pela cidade, e o príncipe o condenou como vulgar. Os rebeldes fizeram sua última resistência no santuário dele. Evitaram o pior, mas a maioria morreu.]=],
		},
		{
			title = "A Fuga",
			text = [=[Os sobreviventes fugiram para o oeste com a frota do príncipe em seu encalço. Além do mar, encontraram uma terra governada por espíritos antigos, e ali firmaram seu pacto com o vento. Os espíritos ergueram a terra até {link:skywall}Skywall{/link}, e os exilados se tornaram os {link:skyborne}shen'dorei{/link}, o povo oculto. Com o tempo, o Shal'nan abdicou de seu governo e o entregou a um conselho escolhido por seu povo.]=],
		},
	},
})
